from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
motor_L = Motor(Port.F, Direction.COUNTERCLOCKWISE)
motor_R = Motor(Port.D, Direction.CLOCKWISE)
att_mtr_L = Motor(Port.B, Direction.CLOCKWISE)
att_mtr_R = Motor(Port.A, Direction.CLOCKWISE)
drive_base = DriveBase(motor_L, motor_R, 86, 132)


# The main program starts here.
drive_base.use_gyro(True)
att_mtr_R.run_angle(500, 150)
drive_base.straight(460, then=Stop.COAST)
